package Patterns;

public class Butterfly {
    public static void printButterfly(int n) {
        // Upper half
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                System.out.print("*"); // Left wing
            }
            for (int j = 1; j <= 2 * (n - i); j++) {
                System.out.print(" "); // Gap between wings
            }
            for (int j = 1; j <= i; j++) {
                System.out.print("*"); // Right wing
            }
            System.out.println();
        }
        // Lower half (mirrors the upper half)
        for (int i = n; i >= 1; i--) {
            for (int j = 1; j <= i; j++) {
                System.out.print("*");
            }
            for (int j = 1; j <= 2 * (n - i); j++) {
                System.out.print(" ");
            }
            for (int j = 1; j <= i; j++) {
                System.out.print("*");
            }
            System.out.println();
        }
    }
    public static void main(String[] args) {
        int n = 5;
        printButterfly(n);
    }
}
